export const getTrailStats = () => {
  const mainTrail = trailSegments.filter(s => s.type === 'main');
  const sideTrails = trailSegments.filter(s => s.type === 'side');

  return {
    mainTrailDistance: mainTrail.reduce((sum, s) => sum + s.distance, 0),
    sideTrailDistance: sideTrails.reduce((sum, s) => sum + s.distance, 0),
    mainTrailSegments: mainTrail.length,
    sideTrailSegments: sideTrails.length,
    totalSegments: trailSegments.length,
    totalDistance: trailSegments.reduce((sum, s) => sum + s.distance, 0),
  };
};

export default trailSegments;
